  'access_personal_information',
  'manage_organisations',
  'manage_organisations_services',
  'manage_organisations_applications',
  'manage_organisations_members',
  'manage_personal_information',
  'manage_ssh_keys',
];

/**
 * @param {string[]} rights Rights to grant
 * @returns {Record<string, boolean>} Rights object expected by the API
 */
export function rightsToApi(rights) {
  return Object.fromEntries(OAUTH_CONSUMER_RIGHTS.map((right) => [right, rights.includes(right)]));
}

/**
 * @param {Record<string, boolean>} rights Rights object returned by the API
 * @returns {string[]} Granted rights
 */
export function grantedRights(rights = {}) {
  return OAUTH_CONSUMER_RIGHTS.filter((right) => rights[right] === true);
}

export function printConsumer(consumer, secret) {
  Logger.println(`${styleText('bold', consumer.name)} ${styleText('blue', `(${consumer.key})`)}`);
  Logger.println(` • Description: ${consumer.description ?? ''}`);
  Logger.println(` • URL: ${consumer.url ?? ''}`);
  Logger.println(` • Base URL: ${consumer.baseUrl ?? ''}`);
  if (consumer.picture) {
    Logger.println(` • Picture: ${consumer.picture}`);
  }
  if (secret != null) {
    Logger.println(` • Secret: ${secret}`);
  }
  const rights = grantedRights(consumer.rights);
  Logger.println(` • Rights: ${rights.length > 0 ? rights.join(', ') : 'none'}`);
}
